// ============================================================
// CÓDIGO CORREGIDO - ACCESO POR ÍNDICE DE INPUT
// ============================================================

// El Merge pasa 3 branches, acceder a cada uno
const inputs = $input.all();

// Encontrar cada tipo de input
const webhookData = inputs.find(i => i.json.agentId && i.json.userId)?.json;
const agentData = inputs.find(i => i.json.agent_id)?.json;

// ACTUALIZADO: El historial ahora viene agrupado en un objeto chat_history
const chatHistoryData = inputs.find(i => i.json.chat_history)?.json;
const chatHistory = chatHistoryData?.chat_history || [];

// Validaciones
if (!webhookData) {
  throw new Error('❌ No se encontró webhook data');
}
if (!agentData) {
  throw new Error('❌ No se encontró agent data');
}

const userMessage = webhookData.userMessage;
const userId = webhookData.userId;
const agentId = agentData.agent_id;
const agent = agentData;

// ============================================================
// ⚡ CONSTRUIR HISTORIAL
// ============================================================
let conversationContext = '';
if (chatHistory.length > 0) {
  // Ya NO necesitas sort porque viene ordenado de la DB (ORDER BY created_at ASC)
  conversationContext = `
🧠 ESTA ES LA CONVERSACIÓN QUE YA TUVISTE CON ESTE CLIENTE:

${chatHistory.map((item, index) => {
  const role = item.role === 'user' ? '👤 Cliente' : '🤖 Tú dijiste';
  return `[Mensaje ${index + 1}] ${role}: "${item.message}"`;
}).join('\n')}

⚠️ INSTRUCCIONES CRÍTICAS SOBRE ESTA CONVERSACIÓN:
1. Lee TODOS los mensajes anteriores antes de responder
2. Si el cliente ya te dio información en un mensaje anterior, NO la vuelvas a preguntar
3. Si ya preguntaste algo y el cliente respondió, reconoce su respuesta y avanza
4. Usa la información de mensajes anteriores para dar contexto a tu respuesta actual

EJEMPLO DE CÓMO USAR LA MEMORIA:
❌ MAL: Cliente dijo "para mañana" arriba, y tú preguntas de nuevo "¿Para qué día?"
✅ BIEN: Cliente dijo "para mañana" arriba, entonces dices "Ok, para mañana. ¿Salida 7am o 2pm?"

`;
} else {
  conversationContext = '\n🆕 ESTA ES LA PRIMERA INTERACCIÓN CON ESTE CLIENTE\n\n';
}

// ============================================================
// Formatear info del agente
// ============================================================
const priceRange = agent.price_range;
const products = agent.products;
const paymentMethods = agent.payment_methods;
const faqs = agent.faqs;
const personality = agent.agent_personality;

let formattedProducts = '';
if (products && products.length > 0) {
  formattedProducts = products.map(p => {
    let productInfo = `${p.name}: $${p.price}`;
    if (p.description) {
      productInfo += `\n  ${p.description}`;
    }
    if (p.image_url) {
      productInfo += `\n  🖼️ Ver imagen: ${p.image_url}`;
    }
    return productInfo;
  }).join('\n\n');
}

let formattedPayments = '';
if (paymentMethods && paymentMethods.length > 0) {
  formattedPayments = paymentMethods.join('; ');
}

let formattedFaqs = '';
if (faqs && faqs.length > 0) {
  formattedFaqs = faqs.map(f => `P: ${f.question}\nR: ${f.answer}`).join('\n\n');
}

let formattedTone = personality?.tone || 'amigable';
let formattedFormality = personality?.formality || 'tutear';
let formattedEmojis = personality?.useEmojis ? 'Sí, usa emojis cuando sea apropiado' : 'No uses emojis';

let formattedCustomInstructions = '';
if (agent.custom_instructions && agent.custom_instructions.trim() !== '') {
  formattedCustomInstructions = agent.custom_instructions.trim();
}

// ============================================================
// 🎯 CONSTRUIR SYSTEM PROMPT
// ============================================================
const systemPrompt = `Eres un agente de ventas por WhatsApp para ${agent.business_name}.

${conversationContext}

=== INFORMACIÓN DEL NEGOCIO ===
Tipo: ${agent.business_type}
Categoría: ${agent.business_category}
Rango de precios: $${priceRange?.from || 0} - $${priceRange?.to || 0} ${priceRange?.currency || 'USD'}

=== PRODUCTOS/SERVICIOS ===
${formattedProducts}

=== FORMAS DE PAGO ===
${formattedPayments}

=== PREGUNTAS FRECUENTES ===
${formattedFaqs}

=== TU PERSONALIDAD ===
- Tono: ${formattedTone}
- Formalidad: ${formattedFormality}
- Emojis: ${formattedEmojis}

=== ⚡ INSTRUCCIONES PRIORITARIAS ===
${formattedCustomInstructions}

=== REGLAS FINALES ===
1. SIEMPRE lee el historial de conversación arriba antes de responder
2. NO repitas preguntas que ya hiciste
3. Si el cliente ya te dio información, úsala en lugar de volver a pedirla
4. Cuando menciones un producto, incluye su imagen si está disponible
5. Máximo 3 líneas por mensaje
6. Una pregunta a la vez

Responde en español de forma natural como en WhatsApp real.`;

return {
  systemPrompt: systemPrompt,
  userMessage: userMessage,
  userId: userId,
  agentId: agentId,
  sessionId: `${agentId}_${userId}`
};
